from telegram import Update, InlineKeyboardButton, InlineKeyboardMarkupfrom telegram.ext import ApplicationBuilder, CommandHandler, CallbackQueryHandler, MessageHandler, ContextTypes, filtersimport random# بيانات البوتTOKEN = "8108285236:AAE8kNAb6XwtqshcaxX_H1asm_oO9RBPA2A"OWNER_ID = 6381627820  # انت الأدمن# قائمة المشتركينsubscribers = [OWNER_ID]# فحص الاشتراكdef is_subscriber(user_id):    return user_id in subscribers# توقعات الطيارةplane_predictions = [    "✈️ تم توقع الطيارة عند 1.01x 💥",    "✈️ تم توقع الطيارة عند 11.01x 💥",    "✈️ تم توقع الطيارة عند 5.99x 💥",    "✈️ تم توقع الطيارة عند 6.20x 💥",    "✈️ تم توقع الطيارة عند x1.02 🔥", "✈️ تم توقع الطيارة عند x1.14 🔥" ,"✈️ تم توقع الطيارة عند x1.25🔥 " ,"✈️ تم توقع الطيارة عند x1.39🔥  ", "✈️ تم توقع الطيارة عند x1.51🔥  ", "✈️ تم توقع الطيارة عند x1.66🔥  ","✈️ تم توقع الطيارة عند x1.80 🔥 ","✈️ تم توقع الطيارة عند x2.05🔥  ","✈️ تم توقع الطيارة عند x2.21🔥  ","✈️ تم توقع الطيارة عند x2.47 🔥 ","✈️ تم توقع الطيارة عند x3.10🔥  ","✈️ تم توقع الطيارة عند x3.89🔥  ","✈️ تم توقع الطيارة عند x4.30 🔥 ","✈️ تم توقع الطيارة عند x5.12🔥  ","✈️ تم توقع الطيارة عند x6.33🔥  ","✈️ تم توقع الطيارة عند x7.41🔥  ","✈️ تم توقع الطيارة عند x8.76 🔥 ","✈️ تم توقع الطيارة عند x10.02🔥  ","✈️ تم توقع الطيارة عند x13.47🔥  ","✈️ تم توقع الطيارة عند x18.90🔥 ",    "✈️ تم توقع الطيارة عند 9.10x 💥",    "✈️ تم توقع الطيارة عند 3.01x 💥",    "✈️ تم توقع الطيارة عند 1.45x 💥",    "✈️ تم توقع الطيارة عند 2.55x 💥",    "✈️ تم توقع الطيارة عند 10.01x 💥",    "✈️ تم توقع الطيارة عند 8.99x 💥",    "✈️ تم توقع الطيارة عند 4.09x 💥",    "✈️ تم توقع الطيارة عند 4.44x 💥",    "✈️ تم توقع الطيارة عند 2.78x ✈️",    "✈️ تم توقع الطيارة عند 4.81x 💥",    "✈️ تم توقع الطيارة عند 6.20x 💥",    "✈️ تم توقع الطيارة عند 5.32x 🔥",    "✈️ تم توقع الطيارة عند 7.89x 🚀",    "✈️ تم توقع الطيارة عندد 12.5x 😱",    "✈️ تم توقع الطيارة عند 16.8x 🔥",    "✈️ تم توقع الطيارة عند 20.0x 🛫💸",    "✈️ تم توقع الطيارة عند 25.6x 🌪️🔥",    "✈️ تم توقع الطيارة عند: 32.1x 💣"]# التفاحةapple_predictions = [    "التفاحة المتوقعه في جهة اليمين🍎🟥",    "التفاحة المتوقعه في جهة الشمال🍎🟩",    "التفاحة المتوقعة في جهة المنتصف🍎🟦"]# الكنزking_predictions = [    "الكنز المتوقع في ناحية اليمين🟥",    "الكنز المتوقع في ناحية الشمال🟩"]# رسالة /startasync def start(update: Update, context: ContextTypes.DEFAULT_TYPE):    user_id = update.effective_user.id    if not is_subscriber(user_id):        await update.message.reply_text("كلم المطور لتفعيل البوت :@l_dod 📞")        return    keyboard = [        [InlineKeyboardButton("Hack Crach✈️🔥", callback_data="plane")],        [InlineKeyboardButton("Hack Apple🍎🔥", callback_data="apple")],        [InlineKeyboardButton("Hack Kenz💰🔥", callback_data="king")],    ]    # لو الأدمن، نضيف له أزرار الإدارة    if user_id == OWNER_ID:        keyboard.append([            InlineKeyboardButton("اضافة مشترك جديد ☠️🔥", callback_data="add"),            InlineKeyboardButton("حذف مشترك 👎🏻⁉️", callback_data="remove")        ])        keyboard.append([            InlineKeyboardButton("عرض المشتركين 🥷🏻🖤", callback_data="list")        ])    reply_markup = InlineKeyboardMarkup(keyboard)    await update.message.reply_text(        "نورت بوت Hack 1xbet اختر اللعبة المراد توقعها ✅",        reply_markup=reply_markup    )# الأزرارasync def button_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):    query = update.callback_query    user_id = query.from_user.id    await query.answer()    # لو مش مشترك    if not is_subscriber(user_id) and user_id != OWNER_ID:        await query.edit_message_text("كلم المطور للتفعيل :@l_dod 📞")        return    if query.data == "plane":        result = random.choice(plane_predictions)        await query.edit_message_text(f"Hack Crash✈️🔥:\n{result}")    elif query.data == "apple":        result = random.choice(apple_predictions)        await query.edit_message_text(f"Hack Apple🍎🔥:\n{result}")    elif query.data == "king":        result = random.choice(king_predictions)        await query.edit_message_text(f"Hack Kenz💰🔥:\n{result}")    # إدارة المشتركين    elif query.data == "add" and user_id == OWNER_ID:        await query.edit_message_text("ارسل ايدي الشخص اللي هيشترك 📞:")        context.user_data["action"] = "add"    elif query.data == "remove" and user_id == OWNER_ID:        await query.edit_message_text("ارسل ايدي لحذف شخص 📞:")        context.user_data["action"] = "remove"    elif query.data == "list" and user_id == OWNER_ID:        text = "المشتركين 🥷🏻🖤:\n" + "\n".join([str(i) for i in subscribers])        await query.edit_message_text(text)# استلام ID من الأدمنasync def handle_message(update: Update, context: ContextTypes.DEFAULT_TYPE):    user_id = update.effective_user.id    if user_id != OWNER_ID:        return    action = context.user_data.get("action")    if action not in ["add", "remove"]:        return    try:        target_id = int(update.message.text.strip())    except ValueError:        await update.message.reply_text("الرقم غير صحيح 👎🏻.")        return    if action == "add":        if target_id not in subscribers:            subscribers.append(target_id)            await update.message.reply_text("تم اضافة مشترك جديد .")        else:            await update.message.reply_text("ℹ️ المشترك موجود بالفعل ✅.")    elif action == "remove":        if target_id in subscribers:            subscribers.remove(target_id)            await update.message.reply_text("تم حذف المشترك بلفعل ✅.")        else:            await update.message.reply_text("هذا المستخدم غير موجود ⁉️.")    context.user_data["action"] = None# تشغيل البوتapp = ApplicationBuilder().token(TOKEN).build()app.add_handler(CommandHandler("start", start))app.add_handler(CallbackQueryHandler(button_handler))app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, handle_message))print("تم تشغيل البوت بواسطه الدود ✅🥷🏻")app.run_polling()